fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    // If the input is empty, just return an empty Vec
    if n == 0 {
        return Vec::new();
    }
    // We know the resulting length will be 2*n - 1
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push each number, inserting `delim` before each element except the first
    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            res.push(delim);
        }
        res.push(num);
    }

    res
}

